use laya::{Agent, Options, Question};
use serde_json::{json, Value};
use std::time::Instant;

fn bench_case(agent: &Agent, name: &str, state: Value, questions: Vec<(String, Question)>, iters: usize) {
    for _ in 0..3 { let _ = agent.system_one(&state, &questions); }
    let mut times: Vec<f64> = Vec::with_capacity(iters);
    for _ in 0..iters {
        let t = Instant::now();
        let r = agent.system_one(&state, &questions).unwrap();
        times.push(t.elapsed().as_secs_f64() * 1000.0);
        let _ = r.usage.input_tokens;
    }
    times.sort_by(|a, b| a.partial_cmp(b).unwrap());
    let mean: f64 = times.iter().sum::<f64>() / times.len() as f64;
    println!("{:<10} mean={:6.1}ms  p50={:6.1}ms  min={:6.1}ms  max={:6.1}ms  (n={})", name, mean, times[iters / 2], times[0], times[iters - 1], iters);
}

fn main() -> anyhow::Result<()> {
    let dir = std::env::args().nth(1).unwrap_or_else(|| "models/laya-base".into());
    let iters: usize = std::env::args().nth(2).and_then(|s| s.parse().ok()).unwrap_or(30);
    let t0 = Instant::now();
    let agent = Agent::from_dir(&dir, Options::default())?;
    println!("model_load  {:?} ({} ms)", dir, t0.elapsed().as_millis());
    let refund_state = json!("I was charged twice. Please refund the duplicate payment.");
    let refund_q = vec![("refund".to_string(), Question::noul("Does the customer ask for money back?"))];
    let urgent_state = json!("The payment gateway has been down for six hours and three enterprise customers are threatening to cancel their contracts unless this is fixed today. Escalating again because the first ticket got no response.");
    let urgent_q = vec![
        ("urgency".to_string(), Question::score("How urgent is this message?", ["routine", "same-day", "drop everything"])),
        ("route".to_string(), Question::choice("Which team should handle it?", ["billing", "technical", "security"])),
    ];
    let r = agent.system_one(&refund_state, &refund_q)?;
    println!("refund answer: {}", serde_json::to_string(&r)?);
    let r = agent.system_one(&urgent_state, &urgent_q)?;
    println!("urgent answer: {}", serde_json::to_string(&r)?);
    bench_case(&agent, "refund", refund_state, refund_q, iters);
    bench_case(&agent, "urgent", urgent_state, urgent_q, iters);
    Ok(())
}
